import type { jsPDF } from 'jspdf';

// ============================================================================
// PDF raporları için Türkçe karakterli yazı tipi (Aşama 10b)
// Liberation Sans (Regular + Bold), yalnızca Latin + Türkçe karakterleri içeren küçültülmüş kopya.
// Lisans: SIL Open Font License 1.1 (uygulamaya gömülerek kullanılması serbesttir).
// Liberation Sans, Helvetica ile aynı harf genişliklerine sahiptir; mevcut PDF düzeni bozulmaz.
// ============================================================================

export const PDF_FONT = 'LiberationSans';

const REGULAR_B64 = [
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
].join('');

const BOLD_B64 = [
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  'Z3JlawA2aGVicgA2bGF0bgA2AAQAAAAA//8AAAAAAAAAAAAA',
].join('');

// Belgeye yazı tipini ekler ve varsayılan yapar. Başarısız olursa false döner (rapor yine üretilir).
export function registerTurkishPdfFont(doc: jsPDF): boolean {
  try {
    doc.addFileToVFS('LiberationSans-Regular.ttf', REGULAR_B64);
    doc.addFont('LiberationSans-Regular.ttf', PDF_FONT, 'normal');
    doc.addFileToVFS('LiberationSans-Bold.ttf', BOLD_B64);
    doc.addFont('LiberationSans-Bold.ttf', PDF_FONT, 'bold');
    doc.setFont(PDF_FONT, 'normal');
    return true;
  } catch (e) {
    console.warn('[PDF] Türkçe yazı tipi yüklenemedi:', e);
    return false;
  }
}
